Method.Implementation:
 Try {
	Set tStatus = $$$OK

	Set tStream = ##class(%Stream.TmpCharacter).%New()
	Set tIOStream = ##class(%IO.MetaCharacterStream).%New(tStream)
	set tStatus = ..PutObject(tIOStream, pObject)
	If $$$ISERR(tStatus) Quit

	Set tStatus = tStream.Rewind()
	If $$$ISERR(tStatus) Quit
	$$$TRACE( "Creating the Stream container for calling TCP OnMessage ")
	Set tStreamObj=##class(%GlobalCharacterStream).%New()
	Set tStatus = tStreamObj.Write($e(tStream.Read(),1,tStream.Size-..DelimiterLength))
	If $$$ISERR(tStatus) Quit

	set pRequest=##class(Ens.StreamContainer).%New(tStreamObj)
	set tStatus=..OnMessage(pRequest,.pResponse)
	if ($$$ISOK(tStatus)){
		If ..Adapter.GetReply {
			set str=pResponse.Stream.Read()
    		$$$TRACE(" The response is "_str)
		}
	}

}
Catch ex {
	Set tStatus = $$$EnsSystemError
}
Quit tStatus

Try {
	set tStatus = $$$OK
	Set tStatus = ..%ValidateObject()
	If $$$ISERR(tStatus) Quit

	If '##class(EnsLib.RecordMap.RecordMap).Exists(..RecordMap) {
		Set tStatus = $$$ERROR($$$ClassDoesNotExist, ..RecordMap)
		Quit
	}

	Set ..recordMapFull = $$$NormalizeClassname(..RecordMap)

	Set tObjectClass = $classmethod(..recordMapFull, "%GetParameter", "OBJECTNAME")
	If '##class(%Dictionary.CompiledClass).%ExistsId(tObjectClass) {
		Set tStatus = $$$ERROR($$$ClassDoesNotExist, tObjectClass)
		Quit
	}
	set tStatus=##super()
}
Catch ex {
	Set tStatus = $$$EnsSystemError
}
Quit tStatus
